package sublist

// Relation type is defined in relations.go file.

func Sublist(l1, l2 []int) Relation {
	if isSubsequence(l1, l2) {
		if len(l1) == len(l2) {
			return RelationEqual
		}
		return RelationSublist
	}
	if isSubsequence(l2, l1) {
		return RelationSuperlist
	}
	return RelationUnequal
}

// isSubsequence reports whether needle appears as a contiguous
// sub-sequence of haystack.
func isSubsequence(needle, haystack []int) bool {
	if len(needle) == 0 {
		return true
	}
	if len(needle) > len(haystack) {
		return false
	}
	for i := 0; i+len(needle) <= len(haystack); i++ {
		matched := true
		for j, v := range needle {
			if haystack[i+j] != v {
				matched = false
				break
			}
		}
		if matched {
			return true
		}
	}
	return false
}
